  Item_Id     BIGINT NOT NULL,                          -- المخزن
  TrnTyp_Id   BIGINT NOT NULL,                          -- نوع الحركة
  CstAcc_Id   BIGINT NOT NULL,                          -- حساب الكلفة
  RevAcc_Id   BIGINT NOT NULL,                          -- حساب الإيراد
  ComAcc_Id   BIGINT NOT NULL,                          -- حساب العمولة
  DisAcc_Id   BIGINT NOT NULL,                          -- حساب الحسم
  PVatAcc_Id  BIGINT DEFAULT 0,                         -- حساب VAT المشتريات
  SVatAcc_Id  BIGINT DEFAULT 0,                         -- حساب VAT المبيعات
  Rem         VARCHAR(100),                          -- ملاحظات
  Ins_User    BIGINT, Ins_Date     DATETIME,
  Upd_User    BIGINT, Upd_Date     DATETIME,
  CONSTRAINT  Stor_SMat_Acc_PK         PRIMARY KEY (Id  ),
  CONSTRAINT  Stor_SMat_Acc_UK         Unique      (Stor_Id, Item_Id, TrnTyp_Id),
  CONSTRAINT  Stor_SMat_Acc_Stor_FK    Foreign Key (Stor_Id   ) References Stor_Store     (Id),
  CONSTRAINT  Stor_SMat_Acc_Item_FK    Foreign Key (Item_Id   ) References Stor_Item      (Id),
  CONSTRAINT  Stor_SMat_Acc_TrnTyp_FK  Foreign Key (TrnTyp_Id ) References Stor_Cod_TrnTyp(Id),
  CONSTRAINT  Stor_SMat_Acc_CstAcc_FK  Foreign Key (CstAcc_Id ) References Acc_Acc        (Id),
  CONSTRAINT  Stor_SMat_Acc_RevAcc_FK  Foreign Key (RevAcc_Id ) References Acc_Acc        (Id),
  CONSTRAINT  Stor_SMat_Acc_ComAcc_FK  Foreign Key (ComAcc_Id ) References Acc_Acc        (Id),
  CONSTRAINT  Stor_SMat_Acc_DisAcc_FK  Foreign Key (DisAcc_Id ) References Acc_Acc        (Id),
  CONSTRAINT  Stor_SMat_Acc_PVatAcc_FK FOREIGN KEY (PVatAcc_Id) REFERENCES Acc_Acc        (Id),
  CONSTRAINT  Stor_SMat_Acc_SVatAcc_FK FOREIGN KEY (SVatAcc_Id) REFERENCES Acc_Acc        (Id),
  CONSTRAINT  Stor_SMat_Acc_Ins_FK     Foreign Key (Ins_User  ) References Cpy_User       (Id),
  CONSTRAINT  Stor_SMat_Acc_Upd_FK     Foreign Key (Upd_User  ) References Cpy_User       (Id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

Create Table Stor_ICS                      -- دليل الباركود - تصنيف المواد
( Id          BIGINT AUTO_INCREMENT,                                  -- مفتاح رئيسي
  Item_Id     BIGINT NOT NULL,                          -- مفتاح المادة
  Unit_Id     BIGINT Default 0,                         -- الوحدة
  Model_Id    BIGINT Default 0,                         -- الموديل
  Color_Id    BIGINT Default 0,                         -- اللون 
  Size_Id     BIGINT Default 0,                         -- القياس 
  nLength     DECIMAL(25,2) Default 0,                      -- الطول
  nWidth      DECIMAL(25,2) Default 0,                      -- العرض
  nHeight     DECIMAL(25,2) Default 0,                      -- الارتفاع
  Qnt         DECIMAL(25,3) Default 0,                      -- الكمية
  BQnt        DECIMAL(25,3) Default 0,                      -- كمية محجوزة
  CQnt        DECIMAL(25,3) Default 0,                      -- الكمية الحالية
  CCst        DECIMAL(25,3) Default 0,                      -- الكلفة الحالية
  CBCst       DECIMAL(25,3) Default 0,                      -- الكلفة الحالية بعملة الأساس
  WQnt        DECIMAL(25,3) Default 0,                      -- الوزن
  BWQnt       DECIMAL(25,3) Default 0,                      -- الوزن المحجوز
  CWQnt       DECIMAL(25,3) Default 0,                      -- الوزن الحالي
  CPrice      DECIMAL(25,2) Default 0 NOT NULL,             -- Current Market سعر السوق الحالي
  NPrice      DECIMAL(25,2) Default 0 NOT NULL,             -- Normal سغر المبيع
  DPrice      DECIMAL(25,2) Default 0 NOT NULL,             -- Discount سعر التخفيضات
  SPrice      DECIMAL(25,2) Default 0 NOT NULL,             -- Sale سعر المواسم
  WPrice      DECIMAL(25,2) Default 0 NOT NULL,             -- Wholesale سعر المبيع جملة
  RPrice      DECIMAL(25,2) Default 0 NOT NULL,             -- Retail سعر المبيع مفرق
  HPrice      DECIMAL(25,2) Default 0 NOT NULL,             -- HalfWhole سعر المبيع نصف الجملة
  MPrice      DECIMAL(25,2) Default 0 NOT NULL,             -- Media السعر في مواقع التواصل الاجتماعي
  Barcode     VARCHAR(50),                           -- مسطرة الترميز
  LotSer      VARCHAR(50) Default '_',               -- طبخة/مسلسل
  SDate       DATETIME Default STR_TO_DATE('01-01-1900', 'DD-MM-YYYY') NOT NULL,-- تاريخ بداية
  EDate       DATETIME Default STR_TO_DATE('01-01-1900', 'DD-MM-YYYY') NOT NULL,-- تاريخ نهاية
  Ins_User    BIGINT, Ins_Date   DATETIME,
  Upd_User    BIGINT, Upd_Date   DATETIME,
  CONSTRAINT  Stor_ICS_PK       PRIMARY KEY (Id),
  CONSTRAINT  Stor_ICS_UK       UNIQUE      (Barcode),
  CONSTRAINT  Stor_ICS_ICS_UK   UNIQUE      (Item_Id, LotSer, Unit_Id, Model_Id, Size_Id, Color_Id, nLength, nWidth, nHeight),
  CONSTRAINT  Stor_ICS_Item_FK  Foreign Key (Item_Id  ) References Stor_Item     (Id),
  CONSTRAINT  Stor_ICS_Unit_FK  Foreign Key (Unit_Id  ) References Cpy_Cod_Unit  (Id),
  CONSTRAINT  Stor_ICS_Model_FK Foreign Key (Model_Id ) References Stor_Cod_Model(Id),
  CONSTRAINT  Stor_ICS_Color_FK Foreign Key (Color_Id ) References Stor_Cod_Color(Id),
  CONSTRAINT  Stor_ICS_Size_FK  Foreign Key (Size_Id  ) References Stor_Cod_Size (Id),
  CONSTRAINT  Stor_ICS_Ins_FK   Foreign Key (Ins_User ) References Cpy_User      (Id),
  CONSTRAINT  Stor_ICS_Upd_FK   Foreign Key (Upd_User ) References Cpy_User      (Id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

