  Src_Id     BIGINT Default 0 NOT NULL,                 -- أصل الأمر
  TrnTyp_Id  BIGINT NOT NULL,                           -- نوع الحركة
  Status_Id  BIGINT Default 0 NOT NULL,                 -- الحالة
  Period_Id  BIGINT NOT NULL,                           -- فترة العمل
  Stor_Id    BIGINT NOT NULL,                           -- المخزن
  Cont_Id    BIGINT NOT NULL,                           -- المتعامل
